/* The county's residents, shown as short adult elves in the photographic game. */
(()=>{'use strict';
const elfDistricts={capital:[['Mara','baker'],['Benn','shopper'],['Guard Alder','guard']],workshop:[['Tobin','shoemaker'],['Iris','weaver'],['Perrin','shopper']],market:[['Nola','stallkeeper'],['Jory','shopper'],['Esme','shopper']],home:[['Hazel','gardener'],['Milo','neighbor'],['Faye','neighbor']],academy:[['Anwen','teacher'],['Kellan','student'],['Sorrel','herbalist']],forest:[['Juniper','ranger'],['Owen','traveler'],['Willow','herbalist']],forgotten:[['Ruth','restoration worker'],['Della','neighbor'],['Corin','carpenter']],festival:[['Lark','musician'],['Pippa','stallkeeper'],['Basil','traveler']],court:[['Guard Briar','guard'],['Guard Flint','guard'],['Nell','royal messenger']],gardens:[['Fernley','gardener'],['Rose','animal keeper'],['Ember','neighbor']],library:[['Ada','librarian'],['Felix','artist'],['Wren','traveler']]};
const elfLines={baker:'The first loaves are ready before sunrise. Come by the tavern when you are hungry.',shopper:'I came for one thing and found three treasures. Have you seen the furnishing shop?',guard:'I patrol the roads and keep the crossings clear. The kingdom is yours to explore.',shoemaker:'A good pair of boots has a hundred journeys in it. The Silverstitch workshop taught me that.',weaver:'Each color tells a story. I am weaving ribbons for the next lantern gathering.',stallkeeper:'We trade stories as often as goods here. There is always room for another customer.',gardener:'These gardens belong to everyone. I water the roots, then leave the blossoms for the bees.',neighbor:'A kingdom feels like home when someone remembers your name. Hello, Templar!',teacher:'My students have a thousand questions. The academy is never quiet for long.',student:'I am practicing my runes. Yesterday I enchanted my own homework by mistake!',herbalist:'Moonleaf likes the river air. The alchemy hall can teach you how to use it.',ranger:'I follow the woodland paths each morning. Listen for the birds above the river.',traveler:'I arrived from beyond the hills. Tonight I will find supper and stories at Moonleaf Tavern.', 'restoration worker':'We are helping this quarter become a place of kindness again, one repaired wall at a time.',carpenter:'There is always something to mend. My next job is a carriage-house shutter.',musician:'I am practicing for the evening gathering. Every festival needs a song.', 'royal messenger':'Letters arrive at the palace from every district. Everyone has a story worth hearing.', 'animal keeper':'The sanctuary creatures know the sound of my footsteps. You can visit them inside.',librarian:'A good book takes you somewhere new, even when your feet stay still.',artist:'I paint the people of Eldoria. A kingdom is more than its towers.'};
const spriteFor={gardener:0,herbalist:0,shoemaker:1,courier:2,traveler:2,neighbor:2,storyteller:3,teacher:4,student:4,librarian:9,baker:5,guard:6,weaver:7,shopper:8,stallkeeper:8,'restoration worker':10,carpenter:1,ranger:10,'royal messenger':2,'animal keeper':0,artist:7,musician:11};
const spriteByName={Mara:5,Benn:8,'Guard Alder':6,Tobin:1,Iris:7,Perrin:8,Nola:11,Jory:6,Esme:7,Hazel:0,Milo:10,Faye:7,Anwen:7,Kellan:2,Sorrel:0,Juniper:10,Owen:2,Willow:0,Ruth:7,Della:9,Corin:1,Lark:11,Pippa:5,Basil:2,'Guard Briar':6,'Guard Flint':1,Nell:2,Fernley:0,Rose:3,Ember:7,Ada:9,Felix:7,Wren:2};
function key(name){return name.toLowerCase().replace(/keeper |master |professor /g,'').replace(/[^a-z0-9]+/g,'_')}
function residents(main){const all=[];for(const [district,people]of Object.entries(elfDistricts)){for(const [name,role]of people)all.push({id:key(name),name,role,district,districts:[district],sprite:spriteByName[name]??spriteFor[role]??2,line:elfLines[role]||elfLines.neighbor});for(const [name,role,line]of main[district]||[]){const existing=all.find(a=>a.id===key(name));if(existing){existing.name=name;existing.line=line;existing.featured=true;if(!existing.districts.includes(district))existing.districts.push(district);continue}const sprite=({'Fern':5,'Master Cobble':1,'Liora':2,'Elian':8,'Moss':0,'Pip':2,'Professor Thistle':4,'Willow':0,'Keeper Willow':0,'Aurelia':3,'Queen Aveline':7,'Archivist Rowan':9,'House historian':4,'Watchkeeper':6})[name]??2;all.push({id:key(name),name,role,district,districts:[district],sprite,line,featured:true})}}return all}
function ensure(s){if(!s.cityElves||typeof s.cityElves!=='object'||Array.isArray(s.cityElves))s.cityElves={};for(const k of ['friends','greeted'])if(!s.cityElves[k]||typeof s.cityElves[k]!=='object'||Array.isArray(s.cityElves[k]))s.cityElves[k]={};return s.cityElves}
function greet(s,person,w,c){const owner={pipHome:'pip',fernHome:'fern',cobbleHome:'cobble',willowHome:'willow'}[w?.room],visiting=owner===person.id||w?.room==='countyCamp'||(w?.room==='cottageSitting'&&person.id==='pip');if(!visiting&&w?.district!==person.district&&!person.districts?.includes(w?.district))return{ok:false,reason:'Meet this elf in their own district first.'};const q=ensure(s),claim=c.key+':'+person.id;if(q.greeted[claim])return{ok:false,reason:'You have already shared today’s conversation. Come back after real midnight, or keep exploring together.'};q.greeted[claim]=true;q.friends[person.id]=(q.friends[person.id]||0)+1;const L=globalThis.EldoriaLifeModel,l=L.ensure(s),core=L.people.find(p=>key(p.name)===person.id);if(core)l.friends[core.id]=(l.friends[core.id]||0)+1;L.stats(s).talks++;l.xp+=2;return{ok:true,title:'A friendly moment with '+person.name}}
globalThis.EldoriaElvesModel={districts:elfDistricts,residents,key,ensure,greet};
})();
